contract InvMutTest is Test {
    EtherLotto c;
    uint constant TICKET = 10;

    function setUp() public { c = new EtherLotto(); }

    function testFuzz_property(address caller, uint256 ts) public {
        vm.assume(caller != address(0));
        ts = bound(ts, 1, type(uint32).max);

        vm.deal(caller, 1 ether);

        vm.warp(ts);

        vm.prank(caller);
        bool ok;
        try c.play{value: TICKET}() {
            ok = true;
        } catch {
            ok = false;
        }

        uint random = uint(keccak256(abi.encodePacked(block.timestamp, block.difficulty, caller))) % 2;

        if (random == 0) {
            assertTrue(c.pot() == 0);
        } else {
            assertTrue(true);
        }
    }
}
